// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        // Call allowance with arbitrary fuzz parameters
        (bool success,) = address(c).call(abi.encodeCall(c.allowance, (owner, spender)));

        // After allowance, try to call file with what='investmentManager'
        // The reference should succeed, the buggy one reverts
        bool fileSuccess;
        bytes memory fileResult;
        (fileSuccess, fileResult) = address(c).call(abi.encodeCall(c.file, ("investmentManager", address(this))));

        // General rule: file call should not revert after allowance call
        assertTrue(fileSuccess, "file() with investmentManager should not revert");
    }
}

